+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Veterinarian;
+import ai.unifiedprocess.petclinic.vet.domain.VeterinarianRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.CallbackDataProvider;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+import java.util.stream.Stream;
+
+/** UC-002: lazily loaded directory of veterinarians and their specialties. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    public VeterinariansView(VeterinarianRepository veterinarians) {
+        Grid<Veterinarian> grid = new Grid<>(Veterinarian.class, false);
+        grid.addColumn(Veterinarian::firstName).setHeader("First name");
+        grid.addColumn(Veterinarian::lastName).setHeader("Last name");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                ? "none"
+                : String.join(", ", vet.specialties())).setHeader("Specialties");
+        grid.setDataProvider(new CallbackDataProvider<>(
+                query -> fetch(veterinarians, query),
+                query -> veterinarians.count()));
+        grid.setWidthFull();
+        setSizeFull();
+        add(grid);
+    }
+
+    private static Stream<Veterinarian> fetch(VeterinarianRepository repository, Query<Veterinarian, ?> query) {
+        return repository.findChunk(query.getOffset(), query.getLimit()).stream();
+    }
+}
